// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue } from '@skyramp/skyramp';
import { postLink, getLinksList, deleteLinks } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const sort = "0";

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "description": "",
        "name": "tb-page-a",
        "tags": [],
        "type": "url",
        "url": "https://example.com/tb-page-a"
    }`;

    const linksPostResponse = await postLink(client, URL_localhost, headers, linksPostRequestBody, 200);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);
    expect(getValue(linksPostResponse, "response.name"), 'name').toBe("tb-page-a");
    expect(getValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/tb-page-a");
    expect(getValue(linksPostResponse, "response.description"), 'description').toBe("");
    expect(getValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    const linkAId = getValue(linksPostResponse, "response.id");

    // Request Body
    const linksPost1RequestBody: string = `{
        "collection": {
            "name": "Unorganized"
        },
        "description": "",
        "name": "tb-page-b",
        "tags": [],
        "type": "url",
        "url": "https://example.com/tb-page-b"
    }`;

    const linksPost1Response = await postLink(client, URL_localhost, headers, linksPost1RequestBody, 200);
    expect(linksPost1Response.statusCode, 'status code').toBe(200);
    expect(getValue(linksPost1Response, "response.name"), 'name').toBe("tb-page-b");
    expect(getValue(linksPost1Response, "response.url"), 'url').toBe("https://example.com/tb-page-b");
    expect(getValue(linksPost1Response, "response.description"), 'description').toBe("");
    expect(getValue(linksPost1Response, "response.type"), 'type').toBe("url");
    expect(getValue(linksPost1Response, "response.id"), 'id').toBeGreaterThan(0);
    expect(getValue(linksPost1Response, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);
    const linkBId = getValue(linksPost1Response, "response.id");
    expect(linkBId, 'the second created link is newer than the first').toBeGreaterThan(linkAId);

    const linksGetResponse = await getLinksList(client, URL_localhost, headers, sort, 200);
    expect(linksGetResponse.statusCode, 'status code').toBe(200);
    const page1 = getValue(linksGetResponse, "response") as any[];
    expect(page1.length, 'the page never exceeds the PAGINATION_TAKE_COUNT default of 50').toBeLessThanOrEqual(50);
    expect(getValue(linksGetResponse, "response.0.id"), 'newest link is first under sort=0').toBe(linkBId);
    expect(getValue(linksGetResponse, "response.0.name"), 'newest link name').toBe("tb-page-b");
    expect(getValue(linksGetResponse, "response.1.id"), 'second newest link').toBe(linkAId);
    expect(getValue(linksGetResponse, "response.1.name"), 'second newest link name').toBe("tb-page-a");
    expect(getValue(linksGetResponse, "response.2"), 'the list holds only the two links this test created').toBeNull();

    const linksGet1Response = await getLinksList(client, URL_localhost, headers, sort, 200, String(linkBId));
    expect(linksGet1Response.statusCode, 'status code').toBe(200);
    const page2 = getValue(linksGet1Response, "response") as any[];
    expect(getValue(linksGet1Response, "response.0.id"), 'the page after the anchor starts at the next older link').toBe(linkAId);
    expect(getValue(linksGet1Response, "response.0.name"), 'the page after the anchor starts at the next older link').toBe("tb-page-a");
    expect(page2.some((link: any) => link.id === linkBId), 'the anchor link is excluded from the page after it').toBe(false);
    expect(getValue(linksGet1Response, "response.1"), 'the page after the anchor holds only the older link').toBeNull();
    expect(page2.length, 'the cursor advanced the page by exactly one link').toBe(page1.length - 1);

    // Request Body
    const linksDeleteRequestBody: string = `{
        "linkIds": [
            ${linkAId},
            ${linkBId}
        ]
    }`;

    const linksDeleteResponse = await deleteLinks(client, URL_localhost, headers, linksDeleteRequestBody, 200);
    expect(linksDeleteResponse.statusCode, 'status code').toBe(200);
    expect(getValue(linksDeleteResponse, "response.count"), 'both links this test created were deleted').toBe(2);
});
